board [
  page [
    sticky id "idea" text "Idea" x 0 y 0 {}
    shape kind DIAMOND id "go" text "Go?" x 300 y 0 {}
    connector from "idea" to "go" {}
  ] {}
] {}..

board [
  page [
    section [
      sticky text "Shipped on time" x 0 y 0 {}
      sticky text "Good pairing" x 280 y 0 {}
    ] name "Went well" x 0 y 0 fill "#ecfdf5" {}
  ] {}
] {}..

board [
  page [
    sticky id "hub" text "Hub" x 300 y 0 {}
    sticky text "A" x 0 y 300 {}
    sticky text "B" x 300 y 300 {}
    sticky text "C" x 600 y 300 {}
    connector from "hub" to ["A" "B" "C"] line-type ELBOWED from-side BOTTOM to-side TOP {}
    connector from "A" to "C" label "related" line-style DASHED from-cap ARROW_LINES {}
  ] {}
] {}..

board [
  page [
    shape kind ROUNDED_RECTANGLE id "test" text "Test" x 0 y 0 {}
    shape kind ROUNDED_RECTANGLE id "build" text "Build" x 0 y 400 {}
    connector from "test" to "build" {}
    connector from "build" to "test" label "fix" from-side LEFT to-side LEFT
      waypoints [ waypoint [-120 _] waypoint [_ 88] ] {}
  ] {}
] {}..

board [
  page [ sticky text "Goals" {} ] name "Planning" {}
  page [ sticky text "Went well" {} ] name "Retro" background "#f5f5f5" {}
] title "Q4 offsite" show-page-menu true {}..

save-to-figjam "https://www.figma.com/board/ABC123/Planning"
board [
  page [ sticky text "Kickoff" {} ] {}
] {}..

board [
  page [
    sticky id "idea" text "Idea" x 0 y 0 {}
    sticky id "plan" text "Plan" x 300 y 0 {}
    connector from "idea" to "plan" {}
  ] {}
] {}..

board [
  page [ sticky text "Goals" {} ] name "Planning" {}
  page [ sticky text "Went well" {} ] name "Retro" background "#f5f5f5" {}
] title "Q4 offsite" {}..

board [
  page [
    shape kind ROUNDED_RECTANGLE id "start" text "Start" x 0 y 0 width 200 height 100 {}
    shape kind DIAMOND id "valid" text "Valid?" x 300 y -20 width 200 height 140 {}
    shape kind ROUNDED_RECTANGLE id "save" text "Save" x 600 y 0 width 200 height 100 {}
    shape kind ROUNDED_RECTANGLE id "error" text "Report error" x 300 y 260 width 200 height 100 {}
    connector from "start" to "valid" {}
    connector from "valid" to "save" label "yes" {}
    connector from "valid" to "error" label "no" from-side BOTTOM to-side TOP line-type ELBOWED {}
  ] {}
] {}..

board [
  page [
    textbox text "Sprint 12 retro" font-size LARGE x 0 y -120 {}
    section [
      sticky text "Shipped on time" fill "#bbf7d0" x 0 y 0 {}
      sticky text "Good pairing" fill "#bbf7d0" x 0 y 280 {}
    ] name "Went well" x 0 y 0 {}
    section [
      sticky text "Flaky tests" fill "#fecaca" x 0 y 0 {}
    ] name "To improve" x 400 y 0 {}
    section [
      sticky text "Quarantine flaky tests" fill "#bfdbfe" x 0 y 0 {}
    ] name "Action items" x 800 y 0 {}
  ] {}
] title "Sprint 12 retro" {}..

save-to-figjam "https://www.figma.com/board/ABC123/Brainstorm"
board [
  page [
    sticky id "hub" text "Idea" x 300 y 300 fill "yellow" {}
    sticky text "Who" x 0 y 0 {}
    sticky text "What" x 600 y 0 {}
    sticky text "Why" x 0 y 600 {}
    sticky text "How" x 600 y 600 {}
    stamp kind CELEBRATE x 560 y 300 {}
    connector from "hub" to ["Who" "What" "Why" "How"] line-style DASHED {}
  ] {}
] {}..

board [
  page [
    sticky id "a" text "Plan" x 0 y 0 {}
    sticky id "b" text "Build" x 300 y 0 {}
    connector from "a" to "b" label "then" {}
  ] {}
] {}..

board [ page [ 
      sticky id "kick" text "Kickoff" x 40 y 80 fill "#ffcc00" opacity 50 font-size MEDIUM {}
      shape kind DIAMOND id "valid" text "Valid?" x 800 y 80 width 200 height 120 stroke "blue" stroke-width THIN {}
      textbox id "title" text "Roadmap" font-size LARGE color "#111111" x 0 y -120 {}
      stamp kind LIKE x 200 y 300 {}
      connector from "kick" to "valid" label "next" line-type ELBOWED line-style DASHED from-cap NONE
        to-cap ARROW_LINES from-side RIGHT to-side LEFT stroke-width THICK {}
     ] {} ] {}..

board [ page [ 
      section [ sticky id "kick" text "Kickoff" x 40 y 80 fill "#ffcc00" {} ] name "Phase 1" x 0 y 0 width 700 height 400 {}
      shape kind DIAMOND id "Valid?" text "Valid?" x 800 y 80 {}
      stamp kind LIKE x 200 y 300 {}
      connector from "kick" to "Valid?" label "next" line-type ELBOWED to-cap ARROW_LINES stroke-width THICK {}
      textbox id "T" text "T" font-size LARGE color "#111111" {}
     ] {} ] {}..

board [ page [ 
      sticky id "a" text "Alpha" {} sticky text "Beta" {} stamp kind LIKE {}
      connector from "a" to "Beta" {}
      connector from "a" to ["Beta" "like"] {}
      connector from "Beta" to "*" {}
     ] {} ] {}..

board [
  page [
    textbox text "Project kickoff" font-size LARGE x 0 y -120 {}
    sticky id "goals" text "Goals" x 0 y 0 {}
    sticky id "risks" text "Risks" x 300 y 0 fill "pink" {}
    shape kind DIAMOND id "go" text "Go?" x 640 y 20 width 200 height 200 {}
    connector from "goals" to "go" line-type ELBOWED {}
    connector from "risks" to "go" line-type ELBOWED {}
    stamp kind LIKE x 220 y 200 {}
  ] {}
] {}..
